            - other[e415] * other[e415]
            - other[e425] * other[e425]
            - other[e435] * other[e435]
            - 2.0 * (other[e423] * other[e235])
            - 2.0 * (other[e431] * other[e315])
            - 2.0 * (other[e412] * other[e125])
            - 2.0 * (other[e4] * other[e5]);
        let geometric_product_g0 = Simd32x3::from(other_g0 * -1.0) * other.group0();
        let geometric_product_g1 = Simd32x4::from(other_g0 * -1.0) * other.group1();
